<?php
if (!defined('ABSPATH')) exit;
/** Remaining Phase 2 community services: notifications, private messages, moderation audit, restrictions and contributor recognition. */
if (!class_exists('BSW_Phase2_Extended')) {
final class BSW_Phase2_Extended {
 public static function init(){
  add_action('init',array(__CLASS__,'register_types'),12);
  add_shortcode('bigshor_notifications',array(__CLASS__,'notifications'));
  add_shortcode('bigshor_messages',array(__CLASS__,'messages'));
  add_shortcode('bigshor_badges',array(__CLASS__,'badges'));
  add_shortcode('bigshor_moderation_log',array(__CLASS__,'moderation_log'));
  add_action('admin_post_bsw_p2_send_message',array(__CLASS__,'send_message'));
  add_action('admin_post_bsw_p2_mark_notification',array(__CLASS__,'mark_notification'));
  add_action('admin_post_bsw_p2_moderate_user',array(__CLASS__,'moderate_user'));
  add_action('show_user_profile',array(__CLASS__,'user_restriction_field'));
  add_action('edit_user_profile',array(__CLASS__,'user_restriction_field'));
  add_action('personal_options_update',array(__CLASS__,'save_user_restriction'));
  add_action('edit_user_profile_update',array(__CLASS__,'save_user_restriction'));
  add_action('wp_login',array(__CLASS__,'check_restriction'),10,2);
  add_action('transition_post_status',array(__CLASS__,'audit_transition'),20,3);
  add_action('wp_insert_comment',array(__CLASS__,'notify_comment'),10,2);
  add_filter('the_content',array(__CLASS__,'link_mentions'),20);
  add_action('save_post_wiki_article',array(__CLASS__,'notify_mentions'),40,3);
 }
 public static function register_types(){
  register_post_type('bsw_notification',array('labels'=>array('name'=>'Wiki Notifications'),'public'=>false,'show_ui'=>true,'show_in_menu'=>'edit.php?post_type=wiki_article','supports'=>array('title','editor'),'capability_type'=>'post','map_meta_cap'=>true));
  register_post_type('bsw_message',array('labels'=>array('name'=>'Contributor Messages'),'public'=>false,'show_ui'=>false,'supports'=>array('title','editor'),'capability_type'=>'post','map_meta_cap'=>true));
  register_post_type('bsw_mod_log',array('labels'=>array('name'=>'Moderation Audit'),'public'=>false,'show_ui'=>current_user_can('manage_options'),'show_in_menu'=>'edit.php?post_type=wiki_article','supports'=>array('title','editor'),'capability_type'=>'post','map_meta_cap'=>true));
 }
 private static function notify($uid,$title,$body,$url=''){
  $uid=absint($uid);if(!$uid||!get_user_by('id',$uid))return 0;
  $id=wp_insert_post(array('post_type'=>'bsw_notification','post_status'=>'publish','post_title'=>sanitize_text_field($title),'post_content'=>wp_kses_post($body),'post_author'=>$uid),true);
  if(!is_wp_error($id)){update_post_meta($id,'_bsw_recipient',$uid);if($url)update_post_meta($id,'_bsw_target_url',esc_url_raw($url));return (int)$id;}return 0;
 }
 public static function notifications(){
  if(!is_user_logged_in())return '<p>Please log in to view notifications.</p>';
  $uid=get_current_user_id();$q=new WP_Query(array('post_type'=>'bsw_notification','post_status'=>'publish','posts_per_page'=>40,'author'=>$uid,'orderby'=>'date','order'=>'DESC'));
  $o='<section class="bsw-notifications"><h2>Notifications</h2>';if(!$q->have_posts())$o.='<p>You have no notifications.</p>';
  while($q->have_posts()){$q->the_post();$id=get_the_ID();$read=get_post_meta($id,'_bsw_read',true);$url=get_post_meta($id,'_bsw_target_url',true);$o.='<article class="bsw-notification"><strong>'.esc_html(get_the_title()).'</strong> '.($read?'<small>Read</small>':'<small>New</small>').'<div>'.wp_kses_post(wpautop(get_the_content())).'</div>';if($url)$o.='<p><a href="'.esc_url($url).'">Open related item</a></p>';if(!$read)$o.='<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="bsw_p2_mark_notification"><input type="hidden" name="notification_id" value="'.(int)$id.'">'.wp_nonce_field('bsw_p2_read_'.$id,'_wpnonce',true,false).'<button>Mark as read</button></form>';$o.='</article>';}
  wp_reset_postdata();return $o.'</section>';
 }
 public static function mark_notification(){ $id=absint($_POST['notification_id']??0);if(!$id||!is_user_logged_in()|| (int)get_post_meta($id,'_bsw_recipient',true)!==get_current_user_id()||!isset($_POST['_wpnonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce'])),'bsw_p2_read_'.$id))wp_die('Not authorised.');update_post_meta($id,'_bsw_read',1);wp_safe_redirect(wp_get_referer()?:home_url('/'));exit; }
 public static function messages(){
  if(!is_user_logged_in())return '<p>Please log in to access contributor messages.</p>';$uid=get_current_user_id();
  $q=new WP_Query(array('post_type'=>'bsw_message','post_status'=>'publish','posts_per_page'=>50,'meta_query'=>array(array('key'=>'_bsw_recipient','value'=>$uid),), 'orderby'=>'date','order'=>'DESC'));
  $o='<section class="bsw-private-messages"><h2>Private contributor messages</h2>';if(!$q->have_posts())$o.='<p>No messages received.</p>';
  while($q->have_posts()){$q->the_post();$sender=(int)get_post_meta(get_the_ID(),'_bsw_sender',true);$u=get_user_by('id',$sender);$o.='<article><h3>'.esc_html(get_the_title()).'</h3><small>From '.esc_html($u?$u->display_name:'Former contributor').' · '.esc_html(get_the_date()).'</small><div>'.wp_kses_post(wpautop(get_the_content())).'</div></article>';}
  wp_reset_postdata();$o.='<h3>Send a message</h3><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="bsw_p2_send_message">'.wp_nonce_field('bsw_p2_send_message','_wpnonce',true,false).'<p><label>Recipient user ID <input type="number" min="1" name="recipient" required></label></p><p><label>Subject <input name="subject" maxlength="120" required></label></p><p><label>Message <textarea name="message" rows="5" required></textarea></label></p><button type="submit">Send message</button></form></section>';return $o;
 }
 public static function send_message(){if(!is_user_logged_in()||!isset($_POST['_wpnonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce'])),'bsw_p2_send_message'))wp_die('Security check failed.');$to=absint($_POST['recipient']??0);$recipient=get_user_by('id',$to);$sender=get_current_user_id();$subject=sanitize_text_field(wp_unslash($_POST['subject']??''));$body=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$recipient||$to===$sender||!$subject||strlen($body)<5)wp_die('Please provide a valid recipient, subject and message.');if(get_user_meta($sender,'_bsw_restricted',true))wp_die('Your account messaging access is restricted.');$id=wp_insert_post(array('post_type'=>'bsw_message','post_status'=>'publish','post_title'=>$subject,'post_content'=>$body,'post_author'=>$sender),true);if(!is_wp_error($id)){update_post_meta($id,'_bsw_sender',$sender);update_post_meta($id,'_bsw_recipient',$to);self::notify($to,'New contributor message','You have received a private message.');}wp_safe_redirect(wp_get_referer()?:home_url('/'));exit; }
 public static function badges($atts){$uid=absint($atts['user']??0);if(!$uid)$uid=get_current_user_id();if(!$uid)return '<p>Sign in to view contributor badges.</p>';$n=count_user_posts($uid,'wiki_article',true);$badges=array();if($n>=1)$badges[]='First Contribution';if($n>=5)$badges[]='Active Contributor';if($n>=25)$badges[]='Knowledge Builder';if($n>=100)$badges[]='Wiki Veteran';$approved=(int)get_user_meta($uid,'_bsw_approved_contributions',true);if($approved>=10)$badges[]='Editorially Trusted';if(!$badges)return '<p>No badges earned yet. Publish your first article to get started.</p>';$o='<ul class="bsw-badges">';foreach($badges as $b)$o.='<li>'.esc_html($b).'</li>';return $o.'</ul>'; }
 public static function audit_transition($new,$old,$post){if(!$post||$post->post_type!=='wiki_article'||$new===$old||wp_is_post_revision($post->ID))return;$actor=get_current_user_id();$msg=sprintf('Article #%d "%s" changed from %s to %s. Actor user ID: %d. Author user ID: %d.',$post->ID,$post->post_title,$old,$new,$actor,(int)$post->post_author);$id=wp_insert_post(array('post_type'=>'bsw_mod_log','post_status'=>'private','post_title'=>'Article status transition: '.$post->post_title,'post_content'=>$msg,'post_author'=>$actor?:1));if($new==='publish'&&$old!=='publish'){$v=(int)get_user_meta($post->post_author,'_bsw_approved_contributions',true);update_user_meta($post->post_author,'_bsw_approved_contributions',$v+1);self::notify($post->post_author,'Article published',$post->post_title.' has been published.',get_permalink($post->ID));}}
 public static function moderation_log(){if(!current_user_can('manage_options')&&!current_user_can('moderate_comments'))return '<p>You do not have permission to view moderation records.</p>';$q=new WP_Query(array('post_type'=>'bsw_mod_log','post_status'=>'private','posts_per_page'=>100,'orderby'=>'date','order'=>'DESC'));$o='<section><h2>Moderation audit log</h2><ul>';while($q->have_posts()){$q->the_post();$o.='<li><strong>'.esc_html(get_the_title()).'</strong> — '.esc_html(get_the_date()).'<p>'.esc_html(get_the_content()).'</p></li>'; }wp_reset_postdata();return $o.'</ul></section>';}
 public static function user_restriction_field($user){if(!current_user_can('manage_options'))return;$restricted=get_user_meta($user->ID,'_bsw_restricted',true);$reason=get_user_meta($user->ID,'_bsw_restriction_reason',true);wp_nonce_field('bsw_restrict_user_'.$user->ID,'bsw_restrict_nonce');echo '<h2>BIGSHOR Wiki account controls</h2><table class="form-table"><tr><th>Restrict contributor</th><td><label><input type="checkbox" name="bsw_restricted" value="1" '.checked($restricted,1,false).'> Prevent login and community messaging</label><p><input class="regular-text" name="bsw_restriction_reason" value="'.esc_attr($reason).'" placeholder="Reason (internal)"></p></td></tr></table>';}
 public static function save_user_restriction($uid){if(!current_user_can('manage_options')||!isset($_POST['bsw_restrict_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_restrict_nonce'])),'bsw_restrict_user_'.$uid))return;$old=get_user_meta($uid,'_bsw_restricted',true);$new=isset($_POST['bsw_restricted'])?1:0;update_user_meta($uid,'_bsw_restricted',$new);update_user_meta($uid,'_bsw_restriction_reason',sanitize_text_field(wp_unslash($_POST['bsw_restriction_reason']??'')));if($old!=$new){$msg='User ID '.$uid.' restriction changed to '.$new.'. Reason: '.sanitize_text_field(wp_unslash($_POST['bsw_restriction_reason']??''));wp_insert_post(array('post_type'=>'bsw_mod_log','post_status'=>'private','post_title'=>'Contributor account restriction updated','post_content'=>$msg,'post_author'=>get_current_user_id()));}}
 public static function moderate_user(){if(!current_user_can('manage_options'))wp_die('Not authorised.');$uid=absint($_POST['user_id']??0);if(!$uid||!isset($_POST['_wpnonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce'])),'bsw_moderate_'.$uid))wp_die('Security check failed.');update_user_meta($uid,'_bsw_restricted',isset($_POST['restricted'])?1:0);wp_safe_redirect(get_edit_user_link($uid));exit;}
 public static function check_restriction($login,$user){if($user instanceof WP_User&&get_user_meta($user->ID,'_bsw_restricted',true)){wp_logout();wp_die('This BIGSHOR Wiki account is currently restricted. Contact the site administrator for assistance.','Account restricted',array('response'=>403));}}
 public static function notify_comment($comment_id,$comment){$post=get_post($comment->comment_post_ID);if(!$post||$post->post_type!=='wiki_article')return;$author=(int)$post->post_author;$commenter=(int)$comment->user_id;if($author&&$author!==$commenter)self::notify($author,'New comment on your article','A new comment was posted on "'.$post->post_title.'".',get_permalink($post->ID).'#comments');}
 public static function link_mentions($content){if(is_admin()||!is_singular('wiki_article'))return $content;return preg_replace_callback('/(?<![\w@])@([A-Za-z0-9_.-]{3,60})/',function($m){$u=get_user_by('login',$m[1]);if(!$u)return esc_html($m[0]);return '<a class="bsw-mention" href="'.esc_url(add_query_arg('contributor',$u->ID,home_url('/contributor/'))).'">@'.esc_html($u->display_name).'</a>';},$content);}
 public static function notify_mentions($post_id,$post,$update){if(wp_is_post_revision($post_id)||wp_is_post_autosave($post_id)||!$post||$post->post_status==='auto-draft')return;if(!current_user_can('edit_post',$post_id))return;if(!preg_match_all('/(?<![\w@])@([A-Za-z0-9_.-]{3,60})/',$post->post_content,$matches))return;$seen=array();foreach(array_unique($matches[1]) as $login){$u=get_user_by('login',$login);if($u&&$u->ID!==get_current_user_id()&&!isset($seen[$u->ID])){self::notify($u->ID,'You were mentioned on BIGSHOR Wiki',$post->post_title.' mentions you.',get_permalink($post_id));$seen[$u->ID]=true;}}}
}
BSW_Phase2_Extended::init();
}
